import 'package:ml_algo/ml_algo.dart';
import 'package:ml_dataframe/ml_dataframe.dart';

void main() {
  final samples = getPimaIndiansDiabetesDataFrame();
  final validator = CrossValidator.kFold(samples, numberOfFolds: 5);
  final createClassifier = (DataFrame data) => LogisticRegressor(data, 'Outcome');
  validator.evaluate(createClassifier, MetricType.accuracy);
}
